/**
 * Every screenshot the landing page shows, in one place. The files are read
 * from `docs/screenshots/` at build time and served under `/docs-media/`,
 * regenerated by `scripts/screenshots/run.sh` (sizes below are theirs).
 */
export interface Screenshot {
  src: string;
  alt: string;
  width: number;
  height: number;
  /** The same screen in the light theme, shown when the visitor's system is light. */
  light?: string;
}

const PHONE = { width: 780, height: 1308 } as const;
const DESKTOP = { width: 1600, height: 1067 } as const;

function shot(file: string, alt: string, size: { width: number; height: number }, lightFile?: string): Screenshot {
  const light = lightFile ? { light: `/docs-media/screenshots/${lightFile}` } : {};
  return { src: `/docs-media/screenshots/${file}`, alt, ...size, ...light };
}

